const ComparisonTypeSchema = z
  .enum([
    'equal',
    'not_equal',
    'less_than',
    'less_than_equal',
    'greater_than',
    'greater_than_equal',
  ])
  .openapi({ description: 'Conditional comparison type' })
  .openapi('ComparisonType')

const MetadataValueSchema = z
  .object({ key: z.string(), value: z.string() })
  .openapi({ required: ['key', 'value'] })
  .openapi('MetadataValue')

const MinorUnitSchema = z
  .preprocess(
    (val) =>
      typeof val === 'number' && Number.isSafeInteger(val)
        ? BigInt(val)
        : typeof val === 'string' && /^-?\d+$/.test(val)
          ? BigInt(val)
          : val,
    z.int64(),
  )
  .openapi({
    type: 'integer',
    format: 'int64',
    description: 'This Unit struct represents MinorUnit in which core amount works',
  })
  .openapi('MinorUnit')

const NumberComparisonSchema = z
  .object({ comparisonType: ComparisonTypeSchema, number: MinorUnitSchema })
  .openapi({
    description: 'Represents a number comparison for "NumberComparisonArrayValue"',
    required: ['comparisonType', 'number'],
  })
  .openapi('NumberComparison')

const ValueTypeSchema = z
  .discriminatedUnion('type', [
    z
      .object({
        type: z.literal('number'),
        value: z
          .preprocess(
            (val) =>
              typeof val === 'number' && Number.isSafeInteger(val)
                ? BigInt(val)
                : typeof val === 'string' && /^-?\d+$/.test(val)
                  ? BigInt(val)
                  : val,
            z.int64().min(0n),
          )
          .openapi({
            type: 'integer',
            format: 'int64',
            minimum: 0,
            description: 'Represents a number literal',
          }),
      })
      .openapi({ required: ['type', 'value'] }),
    z
      .object({
        type: z.literal('enum_variant'),
        value: z.string().openapi({ description: 'Represents an enum variant' }),
      })
      .openapi({ required: ['type', 'value'] }),
    z
      .object({ type: z.literal('metadata_variant'), value: MetadataValueSchema })
      .openapi({ required: ['type', 'value'] }),
    z
      .object({
        type: z.literal('str_value'),
        value: z.string().openapi({ description: 'Represents a arbitrary String value' }),
      })
      .openapi({ required: ['type', 'value'] }),
    z
      .object({
        type: z.literal('global_ref'),
        value: z
          .string()
          .openapi({
            description: 'Represents a global reference, which is a reference to a global variable',
          }),
      })
      .openapi({ required: ['type', 'value'] }),
    z
      .object({
        type: z.literal('number_array'),
        value: z
          .array(
            z
              .preprocess(
                (val) =>
                  typeof val === 'number' && Number.isSafeInteger(val)
                    ? BigInt(val)
                    : typeof val === 'string' && /^-?\d+$/.test(val)
                      ? BigInt(val)
                      : val,
                z.int64().min(0n),
              )
              .openapi({ type: 'integer', format: 'int64', minimum: 0 }),
          )
          .openapi({
            description:
              'Represents an array of numbers. This is basically used for\n"one of the given numbers" operations\neg: payment.method.amount = (1, 2, 3)',
          }),
      })
      .openapi({ required: ['type', 'value'] }),
    z
      .object({
        type: z.literal('enum_variant_array'),
        value: z
          .array(z.string())
          .openapi({
            description:
              'Similar to NumberArray but for enum variants\neg: payment.method.cardtype = (debit, credit)',
          }),
      })
      .openapi({ required: ['type', 'value'] }),
    z
      .object({
        type: z.literal('number_comparison_array'),
        value: z
          .array(NumberComparisonSchema)
          .openapi({
            description:
              'Like a number array but can include comparisons. Useful for\nconditions like "500 < amount < 1000"\neg: payment.amount = (> 500, < 1000)',
          }),
      })
      .openapi({ required: ['type', 'value'] }),
  ])
  .openapi({
    description: 'Represents a value in the DSL',
    discriminator: { propertyName: 'type' },
  })
  .openapi('ValueType')

const ComparisonSchema = z
  .object({
    lhs: z
      .string()
      .openapi({
        description:
          'The left hand side which will always be a domain input identifier like "payment.method.cardtype"',
      }),
    comparison: ComparisonTypeSchema,
    value: ValueTypeSchema,
    metadata: z
      .record(z.string(), z.any())
      .openapi({
        description:
          'Additional metadata that the Static Analyzer and Backend does not touch.\nThis can be used to store useful information for the frontend and is required for communication\nbetween the static analyzer and the frontend.',
      }),
  })
  .openapi({
    description: 'Represents a single comparison condition.',
    required: ['lhs', 'comparison', 'value', 'metadata'],
  })
  .openapi('Comparison')

type IfStatementType = {
  condition: z.infer<typeof ComparisonSchema>[]
  nested?: IfStatementType[] | null
}

const BankTransferInstructionsSchema: z.ZodType<BankTransferInstructionsType> = z
  .lazy(() =>
    z.xor([
      z
        .object({ doku_bank_transfer_instructions: DokuBankTransferInstructionsSchema })
        .openapi({ required: ['doku_bank_transfer_instructions'] }),
      z
        .object({ ach_credit_transfer: AchTransferSchema })
        .openapi({ required: ['ach_credit_transfer'] }),
      z
        .object({ sepa_bank_instructions: SepaBankTransferInstructionsSchema })
        .openapi({ required: ['sepa_bank_instructions'] }),
      z
        .object({ bacs_bank_instructions: BacsBankTransferInstructionsSchema })
        .openapi({ required: ['bacs_bank_instructions'] }),
      z
        .object({ multibanco: MultibancoTransferInstructionsSchema })
        .openapi({ required: ['multibanco'] }),
    ]),
  )
  .openapi('BankTransferInstructions')

const ReceiverDetailsSchema = z
  .object({
    amount_received: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description: 'The amount received by receiver',
      }),
    amount_charged: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        description: 'The amount charged by ACH',
      }),
    amount_remaining: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        description: 'The amount remaining to be sent via ACH',
      }),
  })
  .openapi({ required: ['amount_received'] })
  .openapi('ReceiverDetails')

const BankTransferNextStepsDataSchema = BankTransferInstructionsSchema.and(
  z
    .object({ receiver: ReceiverDetailsSchema.nullable().exactOptional() })
    .openapi({ required: [] }),
).openapi('BankTransferNextStepsData')

const SessionTokenSchema: z.ZodType<SessionTokenType> = z
