const SantanderMandatePeriodicitySchema = z
  .enum(['weekly', 'monthly', 'quarterly', 'semiannually', 'annually'])
  .openapi('SantanderMandatePeriodicity')

const SantanderMandateDetailsSchema = z
  .object({
    fixed_recurring_amount: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64().min(0n),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        minimum: 0,
        description:
          'Fixed amount for each recurring charge in minor units (e.g., cents). If not provided, the mandate will allow variable amounts.',
        example: 6540,
      }),
    min_recurring_amount: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64().min(0n),
      )
      .nullable()
      .exactOptional()
      .openapi({
        type: ['integer', 'null'],
        format: 'int64',
        minimum: 0,
        description:
          'Minimum amount for each recurring charge in minor units (e.g., cents). If not provided, there will be no minimum limit on the amount.',
        example: 6540,
      }),
    start_date: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Start date for the recurring charges. Format: YYYY-MM-DD. If not provided, the mandate will be valid immediately.',
        example: '2026-12-31',
      }),
    end_date: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'End date for the recurring charges. Format: YYYY-MM-DD. If not provided, the mandate will be valid indefinitely.',
        example: '2026-12-31',
      }),
    periodicity: SantanderMandatePeriodicitySchema.nullable().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('SantanderMandateDetails')

