const RecipientBankAccountSchema = z
  .discriminatedUnion('bank_account_type', [
    z
      .object({
        iban: z
          .string()
          .openapi({ description: "The recipient's IBAN.", example: 'GB29NWBK70361331946864' }),
        bank_account_type: z.literal('iban'),
      })
      .openapi({
        description: 'An International Bank Account Number.',
        required: ['iban', 'bank_account_type'],
      }),
    z
      .object({
        account_number: z
          .string()
          .openapi({
            description: "The recipient's bank account number.",
            example: '000123456789',
          }),
        routing_number: z
          .string()
          .openapi({
            description: "The routing number of the recipient's bank.",
            example: '110000000',
          }),
        bank_account_type: z.literal('routing_number'),
      })
      .openapi({
        description: 'A bank account number paired with the routing number of the holding bank.',
        required: ['account_number', 'routing_number', 'bank_account_type'],
      }),
    z
      .object({
        account_number: z
          .string()
          .openapi({ description: "The recipient's bank account number.", example: '09875432' }),
        bic: z
          .string()
          .openapi({
            description: "The Bank Identification Code of the recipient's bank.",
            example: 'HBUKGB4B',
          }),
        bank_account_type: z.literal('bic'),
      })
      .openapi({
        description: 'A bank account number paired with the BIC of the holding bank.',
        required: ['account_number', 'bic', 'bank_account_type'],
      }),
    z
      .object({
        account_number: z
          .string()
          .openapi({
            description: "The recipient's bank account number.",
            example: '000123456789',
          }),
        bank_account_type: z.literal('account_number'),
      })
      .openapi({
        description:
          'A bare bank account number, where the scheme does not require a bank identifier.',
        required: ['account_number', 'bank_account_type'],
      }),
    z
      .object({
        card_isin: z
          .string()
          .max(6)
          .openapi({
            description: "The first six digits of the recipient's PAN.",
            example: '411111',
          }),
        last4: z
          .string()
          .max(4)
          .openapi({
            description: "The last four digits of the recipient's PAN.",
            example: '1111',
          }),
        bank_account_type: z.literal('truncated_pan'),
      })
      .openapi({
        description:
          'A truncated primary account number, made up of the first six and last four digits.',
        required: ['card_isin', 'last4', 'bank_account_type'],
      }),
  ])
  .openapi({ discriminator: { propertyName: 'bank_account_type' } })
  .openapi('RecipientBankAccount')

const RecipientAccountSchema = z
  .xor([
    RecipientBankAccountSchema.and(
      z.object({ type: z.literal('bank_account') }).openapi({ required: ['type'] }),
    ),
    z
      .object({
        card_number: z
          .string()
          .openapi({ description: "The recipient's card number.", example: '4111111111111111' }),
        type: z.literal('card'),
      })
      .openapi({ description: 'Funds are credited to a card.', required: ['card_number', 'type'] }),
    z
      .object({
        wallet_id: z
          .string()
          .openapi({
            description: "The identifier of the recipient's wallet.",
            example: 'wallet_8891',
          }),
        type: z.literal('wallet'),
      })
      .openapi({
        description: 'Funds are credited to a wallet held for the recipient.',
        required: ['wallet_id', 'type'],
      }),
    z
      .object({
        email: z
          .string()
          .openapi({
            description: "The email address that identifies the recipient's account.",
            example: 'jane.doe@example.com',
          }),
        type: z.literal('email'),
      })
      .openapi({
        description: "The recipient's account is identified by their email address.",
        required: ['email', 'type'],
      }),
    z
      .object({
        phone_number: z
          .string()
          .openapi({
            description: "The phone number that identifies the recipient's account.",
            example: '9123456789',
          }),
        type: z.literal('phone'),
      })
      .openapi({
        description: "The recipient's account is identified by their phone number.",
        required: ['phone_number', 'type'],
      }),
    z
      .object({
        social_network_id: z
          .string()
          .openapi({
            description: 'The social network identifier of the recipient.',
            example: 'jane.doe',
          }),
        type: z.literal('social_network'),
      })
      .openapi({
        description: "The recipient's account is identified by a social network handle.",
        required: ['social_network_id', 'type'],
      }),
  ])
  .openapi({
    description: 'The account that receives the funds in an account funded transaction.',
    discriminator: { propertyName: 'type' },
  })
  .openapi('RecipientAccount')

