const ProfileCloneTargetMetadataSchema = z
  .object({
    profile_id: z.string().openapi({ example: 'pro_abcdefghijklmnop' }),
    status: BatchBlocklistJobStatusSchema,
    processed_rows: z
      .int32()
      .min(0)
      .openapi({ description: 'Source entries handled so far for this target.' }),
    error_message: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: "Present when this target's clone failed." }),
  })
  .openapi({
    description: 'Progress of one target profile within a profile-clone job.',
    required: ['profile_id', 'status', 'processed_rows'],
  })
  .openapi('ProfileCloneTargetMetadata')

const ProfileCloneJobMetadataSchema = z
  .object({ targets: z.array(ProfileCloneTargetMetadataSchema) })
  .openapi({
    description: 'Progress of a profile-clone job across its target profiles.',
    required: ['targets'],
  })
  .openapi('ProfileCloneJobMetadata')

const BatchBlocklistJobStatusResponseSchema = z
  .object({
    job_id: z.string(),
    merchant_id: z.string(),
    profile_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The profile that owns this job; for a clone job, the profile whose entries are copied.',
        example: 'pro_abcdefghijklmnop',
      }),
    job_type: BatchBlocklistJobTypeSchema,
    file_name: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The file the merchant uploaded, or the name the export downloads as. Clone jobs return\n`null`.',
      }),
    status: BatchBlocklistJobStatusSchema,
    total_rows: z.int32().min(0),
    succeeded_rows: z.int32().min(0),
    failed_rows: z.int32().min(0),
    metadata: ProfileCloneJobMetadataSchema.nullable().exactOptional(),
    created_at: z.iso.datetime({ offset: true }),
    updated_at: z.iso.datetime({ offset: true }),
    expires_at: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Exports only: when the stored file is removed by the storage lifecycle rule.',
      }),
    downloadable: z
      .boolean()
      .openapi({ description: "Whether this job's file can be fetched right now." }),
    error_message: z.string().nullable().exactOptional(),
    download_url: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Exports only: short-lived signed link, generated per request and never stored. Null in the\nlisting, which does not mint a link per row.',
      }),
    download_url_expires_at: z.iso.datetime({ offset: true }).nullable().exactOptional(),
  })
  .openapi({
    description:
      'One batch blocklist job, as returned by the listing and by `GET /blocklist/batch/{job_id}`.',
    required: [
      'job_id',
      'merchant_id',
      'job_type',
      'status',
      'total_rows',
      'succeeded_rows',
      'failed_rows',
      'created_at',
      'updated_at',
      'downloadable',
    ],
  })
  .openapi('BatchBlocklistJobStatusResponse')

