const BusinessGenericLinkConfigSchema = GenericLinkUiConfigSchema.and(
  z
    .object({
      domain_name: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({ description: 'Custom domain name to be used for hosting the link' }),
      allowed_domains: z
        .array(z.string())
        .superRefine((items, ctx) => {
          const seen = new Map()
          for (const [i, val] of items.entries()) {
            const key = JSON.stringify(val)
            if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
            else seen.set(key, i)
          }
        })
        .openapi({
          description:
            'A list of allowed domains (glob patterns) where this link can be embedded / opened from',
        }),
    })
    .openapi({ required: ['allowed_domains'] }),
).openapi('BusinessGenericLinkConfig')

