const SubscriptionStatusSchema = z
  .enum([
    'active',
    'created',
    'in_active',
    'pending',
    'trial',
    'paused',
    'unpaid',
    'onetime',
    'cancelled',
    'failed',
  ])
  .openapi({
    description:
      'Possible states of a subscription lifecycle.\n\n- `Created`: Subscription was created but not yet activated.\n- `Active`: Subscription is currently active.\n- `InActive`: Subscription is inactive.\n- `Pending`: Subscription is pending activation.\n- `Trial`: Subscription is in a trial period.\n- `Paused`: Subscription is paused.\n- `Unpaid`: Subscription is unpaid.\n- `Onetime`: Subscription is a one-time payment.\n- `Cancelled`: Subscription has been cancelled.\n- `Failed`: Subscription has failed.',
  })
  .openapi('SubscriptionStatus')

