const NextActionDataSchema: z.ZodType<NextActionDataType> = z
  .lazy(() =>
    z
      .discriminatedUnion('type', [
        z
          .object({ redirect_to_url: z.string(), type: z.literal('redirect_to_url') })
          .openapi({
            description: 'Contains the url for redirection flow',
            required: ['redirect_to_url', 'type'],
          }),
        z
          .object({
            popup_url: z.string(),
            redirect_response_url: z.string(),
            type: z.literal('redirect_inside_popup'),
          })
          .openapi({ required: ['popup_url', 'redirect_response_url', 'type'] }),
        z
          .object({
            bank_transfer_steps_and_charges_details: BankTransferNextStepsDataSchema,
            type: z.literal('display_bank_transfer_information'),
          })
          .openapi({
            description:
              'Informs the next steps for bank transfer and also contains the charges details (ex: amount received, amount charged etc)',
            required: ['bank_transfer_steps_and_charges_details', 'type'],
          }),
        z
          .object({
            session_token: SessionTokenSchema.nullable().exactOptional(),
            type: z.literal('third_party_sdk_session_token'),
          })
          .openapi({
            description: 'Contains third party sdk session token response',
            required: ['type'],
          }),
        z
          .object({
            image_data_url: z
              .string()
              .openapi({ description: 'Hyperswitch generated image data source url' }),
            display_to_timestamp: z
              .preprocess(
                (val) =>
                  typeof val === 'number' && Number.isSafeInteger(val)
                    ? BigInt(val)
                    : typeof val === 'string' && /^-?\d+$/.test(val)
                      ? BigInt(val)
                      : val,
                z.int64(),
              )
              .nullable()
              .exactOptional()
              .openapi({ type: ['integer', 'null'], format: 'int64' }),
            qr_code_url: z
              .string()
              .openapi({ description: 'The url for Qr code given by the connector' }),
            display_text: z.string().nullable().exactOptional(),
            border_color: z.string().nullable().exactOptional(),
            raw_qr_data: z
              .string()
              .nullable()
              .exactOptional()
              .openapi({
                description:
                  'The raw QR code data (EMV copy and paste) used for Brazilian payment methods like Pix',
              }),
            type: z.literal('qr_code_information'),
          })
          .openapi({
            description: 'Contains url for Qr code image, this qr code has to be shown in sdk',
            required: ['image_data_url', 'qr_code_url', 'type'],
          }),
        z
          .object({ qr_code_fetch_url: z.string(), type: z.literal('fetch_qr_code_information') })
          .openapi({
            description: 'Contains url to fetch Qr code data',
            required: ['qr_code_fetch_url', 'type'],
          }),
        z
          .object({
            sdk_uri: z.string(),
            display_from_timestamp: z.int(),
            display_to_timestamp: z.int().nullable().exactOptional(),
            poll_config: PollConfigSchema.nullable().exactOptional(),
            type: z.literal('invoke_upi_intent_sdk'),
          })
          .openapi({ required: ['sdk_uri', 'display_from_timestamp', 'type'] }),
        z
          .object({
            qr_code_url: z.string(),
            display_from_timestamp: z.int(),
            display_to_timestamp: z.int().nullable().exactOptional(),
            poll_config: PollConfigSchema.nullable().exactOptional(),
            type: z.literal('invoke_upi_qr_flow'),
          })
          .openapi({ required: ['qr_code_url', 'display_from_timestamp', 'type'] }),
        z
          .object({ voucher_details: z.string(), type: z.literal('display_voucher_information') })
          .openapi({
            description: 'Contains the download url and the reference number for transaction',
            required: ['voucher_details', 'type'],
          }),
        z
          .object({
            display_from_timestamp: z.int(),
            display_to_timestamp: z.int().nullable().exactOptional(),
            poll_config: PollConfigSchema.nullable().exactOptional(),
            type: z.literal('wait_screen_information'),
          })
          .openapi({
            description:
              'Contains duration for displaying a wait screen, wait screen with timer is displayed by sdk',
            required: ['display_from_timestamp', 'type'],
          }),
        z
          .object({ three_ds_data: ThreeDsDataSchema, type: z.literal('three_ds_invoke') })
          .openapi({
            description:
              'Contains the information regarding three_ds_method_data submission, three_ds authentication, and authorization flows',
            required: ['three_ds_data', 'type'],
          }),
        z
          .object({
            next_action_data: SdkNextActionDataSchema,
            type: z.literal('invoke_sdk_client'),
          })
          .openapi({ required: ['next_action_data', 'type'] }),
        z
          .object({
            consent_data_required: MobilePaymentConsentSchema,
            type: z.literal('collect_otp'),
          })
          .openapi({
            description: 'Contains consent to collect otp for mobile payment',
            required: ['consent_data_required', 'type'],
          }),
        z
          .object({ iframe_data: IframeDataSchema, type: z.literal('invoke_hidden_iframe') })
          .openapi({
            description: 'Contains data required to invoke hidden iframe',
            required: ['iframe_data', 'type'],
          }),
        z
          .object({ ddc_data: DDCDataSchema, type: z.literal('invoke_ddc') })
          .openapi({
            description:
              'The data required to trigger the DDC (Device Data Collection) flow by rendering the provided URL in a hidden iframe.',
            required: ['ddc_data', 'type'],
          }),
      ])
      .openapi({ discriminator: { propertyName: 'type' } }),
  )
  .openapi('NextActionData')

