const SupportedPaymentMethodSchema = PaymentMethodSpecificFeaturesSchema.nullable()
  .and(
    z
      .object({
        payment_method: PaymentMethodSchema,
        payment_method_type: PaymentMethodTypeSchema,
        payment_method_type_display_name: z
          .string()
          .openapi({ description: 'The display name of the payment method type' }),
        mandates: FeatureStatusSchema,
        refunds: FeatureStatusSchema,
        supported_capture_methods: z
          .array(CaptureMethodSchema)
          .openapi({
            description: 'List of supported capture methods supported by the payment method type',
          }),
        supported_countries: z
          .array(CountryAlpha3Schema)
          .superRefine((items, ctx) => {
            const seen = new Map()
            for (const [i, val] of items.entries()) {
              const key = JSON.stringify(val)
              if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
              else seen.set(key, i)
            }
          })
          .nullable()
          .exactOptional()
          .openapi({
            description: 'List of countries supported by the payment method type via the connector',
          }),
        supported_currencies: z
          .array(CurrencySchema)
          .superRefine((items, ctx) => {
            const seen = new Map()
            for (const [i, val] of items.entries()) {
              const key = JSON.stringify(val)
              if (seen.has(key)) ctx.addIssue({ code: 'custom', path: [i] })
              else seen.set(key, i)
            }
          })
          .nullable()
          .exactOptional()
          .openapi({
            description:
              'List of currencies supported by the payment method type via the connector',
          }),
      })
      .openapi({
        required: [
          'payment_method',
          'payment_method_type',
          'payment_method_type_display_name',
          'mandates',
          'refunds',
          'supported_capture_methods',
        ],
      }),
  )
  .openapi('SupportedPaymentMethod')

const EventClassSchema = z
  .enum(['payments', 'refunds', 'disputes', 'mandates', 'payouts', 'subscriptions'])
