const LabelInformationSchema = z
  .object({
    label: z.string(),
    target_count: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64().min(0n),
      )
      .openapi({ type: 'integer', format: 'int64', minimum: 0 }),
    target_time: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64().min(0n),
      )
      .openapi({ type: 'integer', format: 'int64', minimum: 0 }),
    mca_id: z.string(),
  })
  .openapi({ required: ['label', 'target_count', 'target_time', 'mca_id'] })
  .openapi('LabelInformation')

const ContractBasedRoutingConfigSchema = z
  .object({
    config: ContractBasedRoutingConfigBodySchema.nullable().exactOptional(),
    label_info: z.array(LabelInformationSchema).nullable().exactOptional(),
  })
  .openapi({ required: [] })
  .openapi('ContractBasedRoutingConfig')

