const WalletResponseDataSchema = z
  .xor([
    z.object({ apple_pay: WalletAdditionalDataForCardSchema }).openapi({ required: ['apple_pay'] }),
    z
      .object({ google_pay: WalletAdditionalDataForCardSchema })
      .openapi({ required: ['google_pay'] }),
    z
      .object({ samsung_pay: WalletAdditionalDataForCardSchema })
      .openapi({ required: ['samsung_pay'] }),
    z.object({ paypal: PaypalWalletAdditionalDataSchema }).openapi({ required: ['paypal'] }),
  ])
  .openapi({
    description:
      'Hyperswitch supports SDK integration with Apple Pay and Google Pay wallets. For other wallets, we integrate with their respective connectors, redirecting the customer to the connector for wallet payments. As a result, we don’t receive any payment method data in the confirm call for payments made through other wallets.',
  })
  .openapi('WalletResponseData')

const WalletResponseSchema = WalletResponseDataSchema.nullable()
