const PayoutTypeSchema = z
  .enum(['card', 'bank', 'wallet', 'bank_redirect'])
  .openapi({
    description:
      'The payout_type of the payout request is a mandatory field for confirming the payouts. It should be specified in the Create request. If not provided, it must be updated in the Payout Update request before it can be confirmed.',
  })
  .openapi('PayoutType')

const PayoutMethodDataResponseSchema = z
  .xor([
    z.object({ card: CardAdditionalDataSchema }).openapi({ required: ['card'] }),
    z.object({ bank: BankAdditionalDataSchema }).openapi({ required: ['bank'] }),
    z.object({ wallet: WalletAdditionalDataSchema }).openapi({ required: ['wallet'] }),
    z
      .object({ bank_redirect: BankRedirectAdditionalDataSchema })
      .openapi({ required: ['bank_redirect'] }),
    z
      .object({ passthrough: PassthroughAdditionalDataSchema })
      .openapi({ required: ['passthrough'] }),
  ])
  .openapi({ description: 'The payout method information for response' })
  .openapi('PayoutMethodDataResponse')

const PayoutsBillingDescriptorSchema = z
  .object({
    reference: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: "Reference displayed on the beneficiary's bank statement." }),
    statement_descriptor: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Statement descriptor displayed for the payout.' }),
  })
  .openapi({ description: 'Billing descriptor information for a payout.', required: [] })
  .openapi('PayoutsBillingDescriptor')

const PayoutEntityTypeSchema = z
  .enum([
    'Individual',
    'Company',
    'NonProfit',
    'PublicSector',
    'NaturalPerson',
    'lowercase',
    'Personal',
  ])
  .openapi({
    description:
      'Type of entity to whom the payout is being carried out to, select from the given list of options',
  })
  .openapi('PayoutEntityType')

const PayoutSendPrioritySchema = z
  .enum(['instant', 'fast', 'regular', 'wire', 'cross_border', 'internal'])
  .openapi({
    description:
      'The send method which will be required for processing payouts, check options for better understanding.',
  })
  .openapi('PayoutSendPriority')

const PayoutAttemptResponseSchema = z
  .object({
    attempt_id: z.string().openapi({ description: 'Unique identifier for the attempt' }),
    status: PayoutStatusSchema,
    amount: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'The payout attempt amount. Amount for the payout in lowest denomination of the currency. (i.e) in cents for USD denomination, in paisa for INR denomination etc.,',
        example: 6583,
      }),
    currency: CurrencySchema.nullable().exactOptional(),
    connector: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'The connector used for the payout' }),
    error_code: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: "Connector's error code in case of failures" }),
    error_message: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: "Connector's error message in case of failures" }),
    payment_method: PayoutTypeSchema.nullable().exactOptional(),
    payout_method_type: PaymentMethodTypeSchema.nullable().exactOptional(),
    connector_transaction_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'A unique identifier for a payout provided by the connector' }),
    cancellation_reason: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'If the payout was cancelled the reason provided here' }),
    unified_code: z
      .string()
      .max(255)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          '(This field is not live yet)\nError code unified across the connectors is received here in case of errors while calling the underlying connector',
        example: 'UE_000',
      }),
    unified_message: z
      .string()
      .max(1024)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          '(This field is not live yet)\nError message unified across the connectors is received here in case of errors while calling the underlying connector',
        example: 'Invalid card details',
      }),
  })
  .openapi({ required: ['attempt_id', 'status', 'amount'] })
  .openapi('PayoutAttemptResponse')

const PayoutLinkResponseSchema = z
  .object({ payout_link_id: z.string(), link: z.string() })
  .openapi({ required: ['payout_link_id', 'link'] })
  .openapi('PayoutLinkResponse')

const PayoutCreateResponseSchema = z
  .strictObject({
    payout_id: z
      .string()
      .length(30)
      .openapi({
        description:
          'Unique identifier for the payout. This ensures idempotency for multiple payouts\nthat have been done by a single merchant. This field is auto generated and is returned in the API response.',
        example: '187282ab-40ef-47a9-9206-5099ba31e432',
      }),
    merchant_id: z
      .string()
      .max(255)
      .openapi({
        description:
          'This is an identifier for the merchant account. This is inferred from the API key\nprovided during the request',
        example: 'merchant_1668273825',
      }),
    merchant_order_reference_id: z
      .string()
      .max(255)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Your unique identifier for this payout or order. This ID helps you reconcile payouts on your system. If provided, it is passed to the connector if supported.',
        example: 'merchant_order_ref_123',
      }),
    amount: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'The payout amount. Amount for the payout in lowest denomination of the currency. (i.e) in cents for USD denomination, in paisa for INR denomination etc.,',
        example: 1000,
      }),
    currency: CurrencySchema,
    connector: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'The connector used for the payout', example: 'wise' }),
    payout_type: PayoutTypeSchema.nullable().exactOptional(),
    payout_method_data: PayoutMethodDataResponseSchema.nullable().exactOptional(),
    source_bank_data: PayoutMethodDataResponseSchema.nullable().exactOptional(),
    billing: AddressSchema.nullable().exactOptional(),
    auto_fulfill: z
      .boolean()
      .default(false)
      .openapi({
        description: 'Set to true to confirm the payout without review, no further action required',
        example: true,
      }),
    customer_id: z
      .string()
      .max(255)
      .openapi({
        description:
          'The identifier for the customer object. If not provided the customer ID will be autogenerated. _Deprecated: Use the customer object instead._',
        deprecated: true,
        example: 'cus_y3oqhf46pyzuxjbcn2giaqnb44',
      }),
    customer: CustomerDetailsResponseSchema.nullable().exactOptional(),
    client_secret: z
      .string()
      .openapi({
        description: "It's a token used for client side verification.",
        example: 'pay_U42c409qyHwOkWo3vK60_secret_el9ksDkiB8hi6j9N78yo',
      }),
    return_url: z
      .string()
      .openapi({
        description: 'The URL to redirect after the completion of the operation',
        example: 'https://hyperswitch.io',
      }),
    business_country: CountryAlpha2Schema,
    business_label: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Business label of the merchant for this payout. _Deprecated: Use profile_id instead._',
        deprecated: true,
        example: 'food',
      }),
    description: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'A description of the payout',
        example: "It's my first payout request",
      }),
    billing_descriptor: PayoutsBillingDescriptorSchema.nullable().exactOptional(),
    entity_type: PayoutEntityTypeSchema,
    recurring: z
      .boolean()
      .default(false)
      .openapi({ description: 'Specifies whether or not the payout request is recurring' }),
    metadata: z
      .object({})
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'You can specify up to 50 keys, with key names up to 40 characters long and values up to 500 characters long. Metadata is useful for storing additional, structured information on an object.',
      }),
    merchant_connector_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Unique identifier of the merchant connector account',
        example: 'mca_sAD3OZLATetvjLOYhUSy',
      }),
    status: PayoutStatusSchema,
    error_message: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'If there was an error while calling the connector the error message is received here',
        example: 'Failed while verifying the card',
      }),
    error_code: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: 'If there was an error while calling the connectors the code is received here',
        example: 'E0001',
      }),
    frm_message: FrmMessageSchema.nullable().exactOptional(),
    profile_id: z
      .string()
      .openapi({ description: 'The business profile that is associated with this payout' }),
    created: z.iso
      .datetime({ offset: true })
      .nullable()
      .exactOptional()
      .openapi({
        description: 'Time when the payout was created',
        example: '2022-09-10T10:11:12Z',
      }),
    connector_transaction_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: "Underlying processor's payout resource ID",
        example: 'S3FC9G9M2MVFDXT5',
      }),
    connector_eligibility_reference_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description: "Underlying processor's reference ID for the payout eligibility check",
        example: '8ad8bf30-5789-52be-a80a-72908abf5f9d',
      }),
    priority: PayoutSendPrioritySchema.nullable().exactOptional(),
    attempts: z
      .array(PayoutAttemptResponseSchema)
      .nullable()
      .exactOptional()
      .openapi({ description: 'List of attempts' }),
    payout_link: PayoutLinkResponseSchema.nullable().exactOptional(),
    email: z
      .string()
      .max(255)
      .nullable()
      .exactOptional()
      .openapi({
        description: "Customer's email. _Deprecated: Use customer object instead._",
        deprecated: true,
        example: 'johntest@test.com',
      }),
    name: z
      .string()
      .max(255)
      .nullable()
      .exactOptional()
      .openapi({
        description: "Customer's name. _Deprecated: Use customer object instead._",
        deprecated: true,
        example: 'John Test',
      }),
    phone: z
      .string()
      .max(255)
      .nullable()
      .exactOptional()
      .openapi({
        description: "Customer's phone. _Deprecated: Use customer object instead._",
        deprecated: true,
        example: '9123456789',
      }),
    phone_country_code: z
      .string()
      .max(255)
      .nullable()
      .exactOptional()
      .openapi({
        description: "Customer's phone country code. _Deprecated: Use customer object instead._",
        deprecated: true,
        example: '+1',
      }),
    unified_code: z
      .string()
      .max(255)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          '(This field is not live yet)\nError code unified across the connectors is received here in case of errors while calling the underlying connector',
        example: 'UE_000',
      }),
    unified_message: z
      .string()
      .max(1024)
      .nullable()
      .exactOptional()
      .openapi({
        description:
          '(This field is not live yet)\nError message unified across the connectors is received here in case of errors while calling the underlying connector',
        example: 'Invalid card details',
      }),
    payout_method_id: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Identifier for payout method' }),
  })
  .openapi({
    required: [
      'payout_id',
      'merchant_id',
      'amount',
      'currency',
      'auto_fulfill',
      'customer_id',
      'client_secret',
      'return_url',
      'business_country',
      'entity_type',
      'recurring',
      'status',
      'profile_id',
    ],
  })
  .openapi('PayoutCreateResponse')

const OutgoingWebhookContentSchema = z
  .discriminatedUnion('type', [
    z
      .object({ type: z.literal('payment_details'), object: PaymentsResponseSchema })
      .openapi({ title: 'PaymentsResponse', required: ['type', 'object'] }),
    z
      .object({ type: z.literal('refund_details'), object: RefundResponseSchema })
      .openapi({ title: 'RefundResponse', required: ['type', 'object'] }),
    z
      .object({ type: z.literal('dispute_details'), object: DisputeResponseSchema })
      .openapi({ title: 'DisputeResponse', required: ['type', 'object'] }),
    z
      .object({ type: z.literal('mandate_details'), object: MandateResponseSchema })
      .openapi({ title: 'MandateResponse', required: ['type', 'object'] }),
    z
      .object({ type: z.literal('payout_details'), object: PayoutCreateResponseSchema })
      .openapi({ title: 'PayoutCreateResponse', required: ['type', 'object'] }),
    z
      .object({
        type: z.literal('subscription_details'),
        object: ConfirmSubscriptionResponseSchema,
      })
      .openapi({ title: 'ConfirmSubscriptionResponse', required: ['type', 'object'] }),
  ])
  .openapi({ discriminator: { propertyName: 'type' } })
  .openapi('OutgoingWebhookContent')

