const PaymentsIncrementalAuthorizationRequestSchema = z
  .object({
    amount: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({
        type: 'integer',
        format: 'int64',
        description:
          'The total amount including previously authorized amount and additional amount',
        example: 6540,
      }),
    reason: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({ description: 'Reason for incremental authorization' }),
    payment_method_data: PaymentMethodDataSchema.nullable().exactOptional(),
  })
  .openapi({ required: ['amount'] })
  .openapi('PaymentsIncrementalAuthorizationRequest')

