const TotalEventsResponseSchema = z
  .object({
    events: z.array(EventListItemResponseSchema).openapi({ description: 'The list of events' }),
    total_count: z
      .preprocess(
        (val) =>
          typeof val === 'number' && Number.isSafeInteger(val)
            ? BigInt(val)
            : typeof val === 'string' && /^-?\d+$/.test(val)
              ? BigInt(val)
              : val,
        z.int64(),
      )
      .openapi({ type: 'integer', format: 'int64', description: 'Count of total events' }),
  })
  .openapi({
    description: 'The response body of list initial delivery attempts api call.',
    required: ['events', 'total_count'],
  })
  .openapi('TotalEventsResponse')

