export const getPaymentsPaymentIdRoute = createRoute({
  method: 'get',
  path: '/payments/{payment_id}',
  tags: ['Payments'],
  summary: 'Payments - Retrieve',
  description:
    'Retrieves a Payment. This API can also be used to get the status of a previously initiated payment or next action for an ongoing payment',
  operationId: 'Retrieve a Payment',
  request: {
    params: z.object({
      payment_id: z
        .string()
        .openapi({
          param: {
            name: 'payment_id',
            in: 'path',
            description: 'The identifier for payment',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      force_sync: z
        .preprocess((val) => (val === 'null' ? null : val), z.stringbool().nullable())
        .exactOptional()
        .openapi({
          param: {
            name: 'force_sync',
            in: 'query',
            description: 'Decider to enable or disable the connector call for retrieve request',
            required: false,
            schema: { type: 'boolean', nullable: true },
          },
        }),
      client_secret: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'client_secret',
            in: 'query',
            description:
              'This is a token which expires after 15 minutes, used from the client to authenticate and create sessions from the SDK',
            required: false,
            schema: { type: 'string', nullable: true },
          },
        }),
      expand_attempts: z
        .preprocess((val) => (val === 'null' ? null : val), z.stringbool().nullable())
        .exactOptional()
        .openapi({
          param: {
            name: 'expand_attempts',
            in: 'query',
            description: 'If enabled provides list of attempts linked to payment intent',
            required: false,
            schema: { type: 'boolean', nullable: true },
          },
        }),
      expand_captures: z
        .preprocess((val) => (val === 'null' ? null : val), z.stringbool().nullable())
        .exactOptional()
        .openapi({
          param: {
            name: 'expand_captures',
            in: 'query',
            description: 'If enabled provides list of captures linked to latest attempt',
            required: false,
            schema: { type: 'boolean', nullable: true },
          },
        }),
    }),
    headers: z.object({
      'X-Connected-Merchant-Id': z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'X-Connected-Merchant-Id',
            in: 'header',
            description:
              "Merchant ID of the connected merchant on whose behalf the operation is performed. Required when authenticating with a platform merchant's API key. Standard and connected merchants must not send it.",
            required: false,
            schema: { type: 'string', nullable: true },
            example: 'merchant_abc',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Gets the payment with final status',
      content: { 'application/json': { schema: PaymentsResponseSchema } },
    },
    404: { description: 'No payment found' },
  },
  security: [{ api_key: [] }, { publishable_key: [] }],
})

