export const postPaymentsPaymentIdConfirmRoute = createRoute({
  method: 'post',
  path: '/payments/{payment_id}/confirm',
  tags: ['Payments'],
  summary: 'Payments - Confirm',
  description:
    'Confirms a payment intent that was previously created with `confirm: false`. This action attempts to authorize the payment with the payment processor.\n\nExpected status transitions after confirmation:\n- `succeeded`: If authorization is successful and `capture_method` is `automatic`.\n- `requires_capture`: If authorization is successful and `capture_method` is `manual`.\n- `failed`: If authorization fails.\nProfile-restricted requests are authorized against the stored payment before payment-method\nprefetch, retry records, address updates, or other confirmation side effects.',
  operationId: 'Confirm a Payment',
  request: {
    params: z.object({
      payment_id: z
        .string()
        .openapi({
          param: {
            name: 'payment_id',
            in: 'path',
            description: 'The identifier for payment',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    headers: z.object({
      'X-Connected-Merchant-Id': z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'X-Connected-Merchant-Id',
            in: 'header',
            description:
              "Merchant ID of the connected merchant on whose behalf the operation is performed. Required when authenticating with a platform merchant's API key. Standard and connected merchants must not send it.",
            required: false,
            schema: { type: 'string', nullable: true },
            example: 'merchant_abc',
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: PaymentsConfirmRequestSchema,
          examples: {
            'Confirm a payment with payment method data': {
              value: {
                customer_acceptance: {
                  acceptance_type: 'online',
                  accepted_at: '1963-05-03T04:07:52.723Z',
                  online: { ip_address: '127.0.0.1', user_agent: 'amet irure esse' },
                },
                payment_method: 'card',
                payment_method_data: {
                  card: {
                    card_cvc: '123',
                    card_exp_month: '10',
                    card_exp_year: '25',
                    card_holder_name: 'joseph Doe',
                    card_number: '4242424242424242',
                  },
                },
                payment_method_type: 'credit',
              },
            },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Payment confirmed',
      content: { 'application/json': { schema: PaymentsCreateResponseOpenApiSchema } },
    },
    400: {
      description: 'Missing mandatory fields',
      content: { 'application/json': { schema: GenericErrorResponseOpenApiSchema } },
    },
  },
  security: [{ api_key: [] }, { publishable_key: [] }],
})

export const postPaymentsPaymentIdCaptureRoute = createRoute({
  method: 'post',
  path: '/payments/{payment_id}/capture',
  tags: ['Payments'],
  summary: 'Payments - Capture',
  description:
    "Captures the funds for a previously authorized payment intent where `capture_method` was set to `manual` and the payment is in a `requires_capture` state.\n\nUpon successful capture, the payment status usually transitions to `succeeded`.\nThe `amount_to_capture` can be specified in the request body; it must be less than or equal to the payment's `amount_capturable`. If omitted, the full capturable amount is captured.\n\nA payment must be in a capturable state (e.g., `requires_capture`). Attempting to capture an already `succeeded` (and fully captured) payment or one in an invalid state will lead to an error.\nWhen authentication restricts access to a profile, the payment must belong to that profile.\nThis authorization is checked before creating a capture record, including for multiple captures.\nPayments outside the authenticated merchant/profile scope are treated as not found.\n",
  operationId: 'Capture a Payment',
  request: {
    params: z.object({
      payment_id: z
        .string()
        .openapi({
          param: {
            name: 'payment_id',
            in: 'path',
            description: 'The identifier for payment',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    headers: z.object({
      'X-Connected-Merchant-Id': z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'X-Connected-Merchant-Id',
            in: 'header',
            description:
              "Merchant ID of the connected merchant on whose behalf the operation is performed. Required when authenticating with a platform merchant's API key. Standard and connected merchants must not send it.",
            required: false,
            schema: { type: 'string', nullable: true },
            example: 'merchant_abc',
          },
        }),
    }),
    body: {
      content: {
        'application/json': {
          schema: PaymentsCaptureRequestSchema,
          examples: {
            'Capture partial amount': { value: { amount_to_capture: 654 } },
            'Capture the full amount': { value: {} },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Payment captured',
      content: { 'application/json': { schema: PaymentsResponseSchema } },
    },
    400: {
      description: 'Missing mandatory fields',
      content: { 'application/json': { schema: GenericErrorResponseOpenApiSchema } },
    },
    404: {
      description: 'Payment not found in the authenticated merchant/profile scope',
      content: { 'application/json': { schema: GenericErrorResponseOpenApiSchema } },
    },
  },
  security: [{ api_key: [] }],
})

