export const getPaymentsListRoute = createRoute({
  method: 'get',
  path: '/payments/list',
  tags: ['Payments'],
  summary: 'Payments - List',
  description: 'To list the *payments*',
  operationId: 'List all Payments',
  request: {
    query: z.object({
      customer_id: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'customer_id',
            in: 'query',
            description: 'The identifier for the customer',
            required: false,
            schema: { type: 'string', nullable: true },
          },
        }),
      starting_after: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'starting_after',
            in: 'query',
            description: 'A cursor for use in pagination, fetch the next list after some object',
            required: false,
            schema: { type: 'string', nullable: true },
          },
        }),
      ending_before: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'ending_before',
            in: 'query',
            description:
              'A cursor for use in pagination, fetch the previous list before some object',
            required: false,
            schema: { type: 'string', nullable: true },
          },
        }),
      limit: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Limit on the number of objects to return',
            required: false,
            schema: { type: 'integer', format: 'int64', nullable: true },
          },
        }),
      created: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        z.iso.datetime({ offset: true }).nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'created',
            in: 'query',
            description: 'The time at which payment is created',
            required: false,
            schema: { type: 'string', format: 'date-time', nullable: true },
          },
        }),
      created_lt: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        z.iso.datetime({ offset: true }).nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'created_lt',
            in: 'query',
            description: 'Time less than the payment created time',
            required: false,
            schema: { type: 'string', format: 'date-time', nullable: true },
          },
        }),
      created_gt: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        z.iso.datetime({ offset: true }).nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'created_gt',
            in: 'query',
            description: 'Time greater than the payment created time',
            required: false,
            schema: { type: 'string', format: 'date-time', nullable: true },
          },
        }),
      created_lte: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        z.iso.datetime({ offset: true }).nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'created_lte',
            in: 'query',
            description: 'Time less than or equals to the payment created time',
            required: false,
            schema: { type: 'string', format: 'date-time', nullable: true },
          },
        }),
      created_gte: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        z.iso.datetime({ offset: true }).nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'created_gte',
            in: 'query',
            description: 'Time greater than or equals to the payment created time',
            required: false,
            schema: { type: 'string', format: 'date-time', nullable: true },
          },
        }),
    }),
    headers: z.object({
      'X-Connected-Merchant-Id': z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'X-Connected-Merchant-Id',
            in: 'header',
            description:
              "Merchant ID of the connected merchant on whose behalf the operation is performed. Required when authenticating with a platform merchant's API key. Standard and connected merchants must not send it.",
            required: false,
            schema: { type: 'string', nullable: true },
            example: 'merchant_abc',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Successfully retrieved a payment list',
      content: { 'application/json': { schema: z.array(PaymentListResponseSchema) } },
    },
    404: { description: 'No payments found' },
  },
  security: [{ api_key: [] }],
})

