export const getCustomersListRoute = createRoute({
  method: 'get',
  path: '/customers/list',
  tags: ['Customers'],
  summary: 'Customers - List',
  description: 'Lists all the customers for a particular merchant id.',
  operationId: 'List all Customers for a Merchant',
  request: {
    query: z.object({
      offset: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int32().min(0),
            )
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description: 'Offset for pagination',
            required: false,
            schema: { type: 'integer', format: 'int32', nullable: true, minimum: 0 },
          },
        }),
      limit: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int32().min(0),
            )
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Limit for pagination',
            required: false,
            schema: { type: 'integer', format: 'int32', nullable: true, minimum: 0 },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Customers retrieved',
      content: { 'application/json': { schema: z.array(CustomerResponseSchema) } },
    },
    400: { description: 'Invalid Data' },
  },
  security: [{ api_key: [] }],
})

