export const getAccountPaymentMethodsRoute = createRoute({
  method: 'get',
  path: '/account/payment_methods',
  tags: ['Payment Methods'],
  summary: 'List payment methods for a Merchant',
  description:
    'Lists the applicable payment methods for a particular Merchant ID.\nUse the client secret and publishable key authorization to list all relevant payment methods of the merchant for the payment corresponding to the client secret.',
  operationId: 'List all Payment Methods for a Merchant',
  request: {
    query: z.object({
      client_secret: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'client_secret',
            in: 'query',
            description:
              'This is a token which expires after 15 minutes, used from the client to authenticate and create sessions from the SDK',
            required: false,
            schema: { type: 'string', nullable: true },
          },
        }),
      accepted_countries: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(CountryAlpha2Schema),
        )
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'accepted_countries',
            in: 'query',
            description: 'The two-letter ISO currency code',
            required: false,
            schema: {
              type: 'array',
              items: { $ref: '#/components/schemas/CountryAlpha2' },
              nullable: true,
            },
          },
        }),
      accepted_currencies: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(CurrencySchema),
        )
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'accepted_currencies',
            in: 'query',
            description: 'The three-letter ISO currency code',
            required: false,
            schema: {
              type: 'array',
              items: { $ref: '#/components/schemas/Currency' },
              nullable: true,
            },
          },
        }),
      amount: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'amount',
            in: 'query',
            description: 'The amount accepted for processing by the particular payment method.',
            required: false,
            schema: { type: 'integer', format: 'int64', nullable: true },
          },
        }),
      recurring_enabled: z
        .preprocess((val) => (val === 'null' ? null : val), z.stringbool().nullable())
        .exactOptional()
        .openapi({
          param: {
            name: 'recurring_enabled',
            in: 'query',
            description: 'Indicates whether the payment method is eligible for recurring payments',
            required: false,
            schema: { type: 'boolean', nullable: true },
          },
        }),
      installment_payment_enabled: z
        .preprocess((val) => (val === 'null' ? null : val), z.stringbool().nullable())
        .exactOptional()
        .openapi({
          param: {
            name: 'installment_payment_enabled',
            in: 'query',
            description:
              'Indicates whether the payment method is eligible for installment payments',
            required: false,
            schema: { type: 'boolean', nullable: true },
          },
        }),
      limit: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Indicates the limit of last used payment methods',
            required: false,
            schema: { type: 'integer', format: 'int64', nullable: true },
          },
        }),
      card_networks: z
        .preprocess(
          (val) => (val === undefined || Array.isArray(val) ? val : [val]),
          z.array(CardNetworkSchema),
        )
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'card_networks',
            in: 'query',
            description: 'Indicates whether the payment method is eligible for card netwotks',
            required: false,
            schema: {
              type: 'array',
              items: { $ref: '#/components/schemas/CardNetwork' },
              nullable: true,
            },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Payment Methods retrieved',
      content: { 'application/json': { schema: PaymentMethodListResponseSchema } },
    },
    400: { description: 'Invalid Data' },
    404: { description: 'Payment Methods does not exist in records' },
  },
  security: [{ api_key: [] }, { publishable_key: [] }],
})

