export const getBlocklistBatchRoute = createRoute({
  method: 'get',
  path: '/blocklist/batch',
  tags: ['Blocklist'],
  operationId: 'List batch blocklist jobs',
  request: {
    query: z.object({
      limit: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int32().min(0),
            )
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Maximum number of jobs to return (default 10, max 100)',
            required: false,
            schema: { type: 'integer', format: 'int32', nullable: true, minimum: 0 },
          },
        }),
      offset: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int32().min(0),
            )
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description: 'Zero-based offset for pagination (default 0)',
            required: false,
            schema: { type: 'integer', format: 'int32', nullable: true, minimum: 0 },
          },
        }),
      job_type: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        BatchBlocklistJobTypeSchema.nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'job_type',
            in: 'query',
            description:
              'Restricts the listing to `upload`, `export`, or `profile_clone` jobs. All kinds are returned when omitted, newest first.',
            required: false,
            schema: {
              allOf: [{ $ref: '#/components/schemas/BatchBlocklistJobType' }],
              nullable: true,
            },
          },
        }),
    }),
    headers: z.object({
      'X-Profile-Id': z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'X-Profile-Id',
            in: 'header',
            description:
              "Restricts the listing to jobs run for this business profile, plus jobs that predate profile scoping. When no profile can be resolved, all of the merchant's jobs are returned, as before.",
            required: false,
            schema: { type: 'string', nullable: true },
          },
        }),
      'X-Connected-Merchant-Id': z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'X-Connected-Merchant-Id',
            in: 'header',
            description:
              "Merchant ID of the connected merchant on whose behalf the operation is performed. Required when authenticating with a platform merchant's API key. Standard and connected merchants must not send it.",
            required: false,
            schema: { type: 'string', nullable: true },
            example: 'merchant_abc',
          },
        }),
    }),
  },
  responses: {
    200: {
      description:
        'List of batch blocklist jobs. Rows report `downloadable`, but never `download_url` - fetch the link from `GET /blocklist/batch/{job_id}` when the merchant asks for that specific file.',
      content: { 'application/json': { schema: ListBatchBlocklistJobsResponseSchema } },
    },
  },
  security: [{ api_key: [] }, { jwt_key: [] }],
})

export const postBlocklistBatchRoute = createRoute({
  method: 'post',
  path: '/blocklist/batch',
  tags: ['Blocklist'],
  operationId: 'Upload a batch blocklist CSV',
  request: {
    query: z.object({
      transaction_type: ((schema) =>
        z.union([schema, z.preprocess((val) => (val === 'null' ? null : val), schema)]))(
        BlocklistTransactionTypeSchema.nullable(),
      )
        .exactOptional()
        .openapi({
          param: {
            name: 'transaction_type',
            in: 'query',
            description:
              'Overrides every CSV row with payment or payout when selected. When omitted, row selections are used; missing or empty row values default to payment.',
            required: false,
            schema: {
              allOf: [{ $ref: '#/components/schemas/BlocklistTransactionType' }],
              nullable: true,
            },
          },
        }),
    }),
    headers: z.object({
      'X-Profile-Id': z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'X-Profile-Id',
            in: 'header',
            description:
              'The business profile every entry in this upload is blocked under. Resolution follows the same rules as blocking a single entry.',
            required: false,
            schema: { type: 'string', nullable: true },
          },
        }),
      'X-Connected-Merchant-Id': z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'X-Connected-Merchant-Id',
            in: 'header',
            description:
              "Merchant ID of the connected merchant on whose behalf the operation is performed. Required when authenticating with a platform merchant's API key. Standard and connected merchants must not send it.",
            required: false,
            schema: { type: 'string', nullable: true },
            example: 'merchant_abc',
          },
        }),
    }),
    body: {
      description:
        "A multipart/form-data request with a `file` field containing a UTF-8 CSV (max 5 MiB). The part's `filename` is recorded on the job and returned as `file_name`. The CSV header is `type,data,metadata,transaction_type`; older headers without `transaction_type` are accepted. `type`: one of `generic_card_bin` (6 to 10 digits), `card_bin` (6 digits), `extended_card_bin` (8 digits), `fingerprint`. `metadata`: optional, `key=value` pairs separated by `;` (e.g. `reason=fraud;source=manual`). `transaction_type`: optional, `payment` (default) or `payout`; selection may differ per row. Invalid CSV transaction-type values are rejected even when a query override is selected. Maximum 100,000 data rows.",
      content: { 'multipart/form-data': { schema: z.string() } },
      required: true,
    },
  },
  responses: {
    202: {
      description: 'Batch blocklist job initiated',
      content: { 'application/json': { schema: BatchBlocklistUploadResponseSchema } },
    },
    400: {
      description:
        'CSV validation error, file exceeds 5 MiB limit, or no profile could be resolved',
    },
  },
  security: [{ api_key: [] }, { jwt_key: [] }],
})

