export const getApiKeysMerchantIdListRoute = createRoute({
  method: 'get',
  path: '/api_keys/{merchant_id}/list',
  tags: ['API Key'],
  summary: 'API Key - List',
  description: 'List all the API Keys associated to a merchant account.',
  operationId: 'List all API Keys associated with a merchant account',
  request: {
    params: z.object({
      merchant_id: z
        .string()
        .openapi({
          param: {
            name: 'merchant_id',
            in: 'path',
            description: 'The unique identifier for the merchant account',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      limit: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'The maximum number of API Keys to include in the response',
            required: false,
            schema: { type: 'integer', format: 'int64', nullable: true },
          },
        }),
      skip: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess((val) => {
              if (typeof val !== 'string' || !/^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val))
                return val
              if (/^-?\d+$/.test(val)) return BigInt(val)
              const num = Number(val)
              return Number.isSafeInteger(num) ? BigInt(num) : val
            }, z.int64())
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'skip',
            in: 'query',
            description: 'The number of API Keys to skip when retrieving the list of API keys.',
            required: false,
            schema: { type: 'integer', format: 'int64', nullable: true },
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'List of API Keys retrieved successfully',
      content: { 'application/json': { schema: z.array(RetrieveApiKeyResponseSchema) } },
    },
  },
  security: [{ admin_api_key: [] }],
})

