export const getSubscriptionsItemsRoute = createRoute({
  method: 'get',
  path: '/subscriptions/items',
  tags: ['Subscriptions'],
  summary: 'Subscription - Get Items',
  description: 'Retrieves available subscription items.',
  operationId: 'Get Subscription Items',
  request: {
    headers: z.object({
      'X-Profile-Id': z
        .string()
        .openapi({
          param: {
            name: 'X-Profile-Id',
            in: 'header',
            description: 'Profile ID for authentication',
            required: true,
            schema: { type: 'string' },
          },
        }),
    }),
    query: z.object({
      limit: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int32().min(0),
            )
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'limit',
            in: 'query',
            description: 'Number of items to retrieve',
            required: false,
            schema: { type: 'integer', format: 'int32', nullable: true, minimum: 0 },
          },
        }),
      offset: z
        .preprocess(
          (val) => (val === 'null' ? null : val),
          z
            .preprocess(
              (val) =>
                typeof val === 'string' &&
                /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                  ? Number(val)
                  : val,
              z.int32().min(0),
            )
            .nullable(),
        )
        .exactOptional()
        .openapi({
          param: {
            name: 'offset',
            in: 'query',
            description: 'Number of items to skip',
            required: false,
            schema: { type: 'integer', format: 'int32', nullable: true, minimum: 0 },
          },
        }),
      product_id: z
        .string()
        .nullable()
        .exactOptional()
        .openapi({
          param: {
            name: 'product_id',
            in: 'query',
            description: 'Filter by product ID',
            required: false,
            schema: { type: 'string', nullable: true },
          },
        }),
      item_type: SubscriptionItemTypeSchema.openapi({
        param: {
          name: 'item_type',
          in: 'query',
          description: 'Filter by subscription item type plan or addon',
          required: true,
          schema: { $ref: '#/components/schemas/SubscriptionItemType' },
        },
      }),
    }),
  },
  responses: {
    200: {
      description: 'List of available subscription items',
      content: { 'application/json': { schema: z.array(GetSubscriptionItemsResponseSchema) } },
    },
    400: { description: 'Invalid query parameters' },
  },
  security: [{ api_key: [] }, { client_secret: [] }],
})

